<?php
declare(strict_types=1);
namespace OMT;
require_once __DIR__.'/employee-auth.php';require_once __DIR__.'/employee-recovery.php';
function employeeSecret(array $settings):string{$secret=$settings['JWT_SECRET']??'';if(strlen($secret)<16)throw new HttpError(503,'Employee authentication is unavailable');return hash_hmac('sha256','employee-portal-v1',$secret);}
function requireEmployee(Store $store,array $settings,string $token):array{$claims=verifyToken($token,employeeSecret($settings));if(($claims['type']??'')!=='employee')throw new HttpError(401,'Invalid employee token');$a=$store->get('employeeaccounts',$claims['id']);if(!$a||!$store->get('employees',(string)($a['employee']??'')))throw new HttpError(401,'Employee account not found');if(empty($a['loginEnabled']))throw new HttpError(403,'Employee login is disabled');if(($claims['version']??null)!==(int)($a['sessionVersion']??0))throw new HttpError(401,'Please log in again');if(!empty($a['isFirstLogin']))throw new HttpError(403,'Set your password using WhatsApp OTP first');return safeAccount($a);}
final class EmployeeAccounts {
 public function __construct(private readonly Store $store){}
 public function status(string $employee):?array{$a=$this->store->first('employeeaccounts',fn($a)=>$a['employee']===$employee);return $a?array_intersect_key($a,array_flip(['userId','loginEnabled','isFirstLogin','revision'])):null;}
 public function ensure(string $id,string $actor):array{return $this->store->transaction(function()use($id,$actor){$this->store->prepareEmployeeCollections();$e=$this->store->get('employees',$id)??throw new HttpError(404,'Employee not found');$a=$this->store->first('employeeaccounts',fn($a)=>$a['employee']===$id);if(!$a){$userId='EMP-'.strtoupper(substr($id,-8));while($this->store->first('employeeaccounts',fn($a)=>$a['userId']===$userId))$userId='EMP-'.strtoupper(bin2hex(random_bytes(4)));$a=$this->store->put('employeeaccounts',['employee'=>$id,'userId'=>$userId,'passwordHash'=>password_hash(bin2hex(random_bytes(32)),PASSWORD_BCRYPT,['cost'=>12]),'isFirstLogin'=>true,'loginEnabled'=>true,'failedLoginAttempts'=>0,'lockedUntil'=>null,'passwordChangedAt'=>null,'revision'=>1,'sessionVersion'=>0],true);$this->store->put('employeeaudit',['type'=>'login-account-created','target'=>$id,'actor'=>$actor,'after'=>['employee'=>$id,'userId'=>$userId]],true);}return success($this->status($id));});}
 public function toggle(string $id,array $b,string $actor):array{return $this->store->transaction(function()use($id,$b,$actor){$a=$this->store->first('employeeaccounts',fn($a)=>$a['employee']===$id)??throw new HttpError(404,'Create the employee login first');if(!is_bool($b['loginEnabled']??null))throw new HttpError(400,'Choose ON or OFF');if(($b['revision']??null)!==($a['revision']??1))throw new HttpError(409,'Login settings changed. Refresh and retry.');$a['loginEnabled']=$b['loginEnabled'];$a['revision']=($a['revision']??1)+1;$a['sessionVersion']=($a['sessionVersion']??0)+1;$this->store->put('employeeaccounts',$a);$this->store->put('employeeaudit',['type'=>'login-access','target'=>$id,'actor'=>$actor,'after'=>['employee'=>$id,'loginEnabled'=>$a['loginEnabled']]],true);return success($this->status($id));});}
 public function dashboard(array $a,string $month):array{$d=(new Employees($this->store))->detail($a['employee'],$month)[1]['data'];$d['employee']=array_intersect_key($d['employee'],array_flip(['_id','name','phone','joiningDate','endDate','terms','salaryCycleDay']));unset($d['audit'],$d['notifications'],$d['loginAccount']);foreach(['salaryPayments','cashEntries','advanceRecoveries']as $key)$d[$key]=array_map(fn($p)=>array_diff_key($p,array_flip(['actor','fingerprint'])),$d[$key]);$d['payroll']['payments']=array_map(fn($p)=>array_diff_key($p,array_flip(['actor','fingerprint'])),$d['payroll']['payments']);$d['userId']=$a['userId'];return success($d);}
 public function slip(array $a,string $id):array{$p=$this->store->get('salarypayments',$id);if(!$p||$p['employee']!==$a['employee'])throw new HttpError(404,'Salary slip not found');return (new Employees($this->store))->slip($id);}
}
